cd /home/user/rork-app && echo "=== GitHub main branch (your repo) ===" && curl -s "https://api.github.com/repos/ibb142/ivx-holdings-platform/branches/main" -H "Authorization: token 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" 2>&1 | bun -e "
const d = await Bun.stdin.text().then(JSON.parse);
