" && echo "" && echo "=== Recent commits on GitHub main (last 5) ===" && curl -s "https://api.github.com/repos/ibb142/ivx-holdings-platform/commits?per_page=5" -H "Authorization: token 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" 2>&1 | bun -e "
const d = await Bun.stdin.text().then(JSON.parse);
for (const c of d) {
  console.log(c.sha.slice(0,10), '|', c.commit.message.split('\n')[0], '|', c.commit.author.date);
}
" && echo "" && echo "=== Production runtime SHA (Render) ===" && curl -s "https://ivx-holdings-platform.onrender.com/health" 2>&1 | bun -e "
const d = await Bun.stdin.text().then(JSON.parse);
console.log('Deployed SHA:', d.commit);
console.log('Status:', d.status);
console.log('Boot time:', d.bootTime);
"

